package com.insurance.claim.controller;
import com.insurance.claim.dto.ClaimResponse; import com.insurance.claim.dto.CreateClaimRequest; import com.insurance.claim.service.ClaimService;
import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/claims") public class ClaimController { private final ClaimService claimService; public ClaimController(ClaimService claimService){this.claimService=claimService;} @PostMapping @PreAuthorize("hasAnyRole('CUSTOMER','ADJUSTER','ADMIN')") public ResponseEntity<ClaimResponse> createClaim(@Valid @RequestBody CreateClaimRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(claimService.createClaim(request));}}
